using Microsoft.SqlServer.TransactSql.ScriptDom;
using Seamless.Database.Gateway.Hosting;
using Seamless.Database.Query;
using Seamless.Database.Rdbms;

namespace Seamless.Database.Gateway.Sql;

internal static class GatewayComputedExpressions{
    internal static (string Sql,ColumnCatalog[] Inputs) Rewrite(string expression,TableCatalog table){
        var sql="SELECT "+expression;var script=new TSql160Parser(true).Parse(new StringReader(sql),out var errors);if(errors.Count!=0){throw new SqlQueryException(errors[0].Message,102);}var visitor=new References();script.Accept(visitor);var columns=new List<ColumnCatalog>();foreach(var reference in visitor.Columns){if(reference.MultiPartIdentifier.Identifiers.Count!=1){throw new SqlQueryException("A computed column requires unqualified column names.",107);}var column=table.Columns.SingleOrDefault(column=>column.Name.Equals(reference.MultiPartIdentifier.Identifiers[0].Value,StringComparison.OrdinalIgnoreCase))??throw new SqlQueryException("Invalid column in computed expression.",207);if(column.ComputedDefinition is not null){throw new SqlQueryException("A computed column cannot refer to another computed column.",1759);}if(!columns.Contains(column)){columns.Add(column);}}
        foreach(var reference in visitor.Columns.OrderByDescending(static reference=>reference.StartOffset)){var name=reference.MultiPartIdentifier.Identifiers[0].Value;var ordinal=columns.FindIndex(column=>column.Name.Equals(name,StringComparison.OrdinalIgnoreCase));sql=sql.Remove(reference.StartOffset,reference.FragmentLength).Insert(reference.StartOffset,"@c"+ordinal);}return(sql,columns.ToArray());
    }
    internal static SqlParameter[] Parameters(IReadOnlyList<ColumnCatalog> columns)=>columns.Select((column,index)=>new SqlParameter("@c"+index,ComparisonHost.ToSqlType(column.Type),column.Type.IsNullable){IsColumnValue=true}).ToArray();
    internal static DatabaseType Infer(SqlType type,bool nullable){
        var clr=type.ClrType;var kind=clr==typeof(int)?DatabaseTypeKind.Int32:clr==typeof(long)?DatabaseTypeKind.Int64:clr==typeof(short)?DatabaseTypeKind.Int16:clr==typeof(byte)?DatabaseTypeKind.Byte:clr==typeof(bool)?DatabaseTypeKind.Boolean:clr==typeof(decimal)?DatabaseTypeKind.Decimal:clr==typeof(double)?DatabaseTypeKind.Double:clr==typeof(float)?DatabaseTypeKind.Single:clr==typeof(string)?DatabaseTypeKind.String:clr==typeof(byte[])?DatabaseTypeKind.Binary:clr==typeof(Guid)?DatabaseTypeKind.Guid:clr==typeof(DateTime)?DatabaseTypeKind.DateTime:clr==typeof(DateOnly)?DatabaseTypeKind.Date:clr==typeof(TimeOnly)?DatabaseTypeKind.Time:clr==typeof(DateTimeOffset)?DatabaseTypeKind.DateTimeOffset:throw new SqlQueryException("The computed result needs a persistent SQL representation.",40515);if(clr==typeof(decimal)&&type.Precision>28){throw new SqlQueryException("Computed decimal precision above 28 needs a wider representation.",40515);}return new(kind,nullable,type.Length,type.Precision,type.Scale,SqlTypeName:type.Name,Collation:type.Collation);
    }
    internal static void ValidatePersisted(string expression,DatabaseCatalog catalog,HashSet<string>? active=null){
        var script=new TSql160Parser(true).Parse(new StringReader("SELECT "+expression),out _);var visitor=new References();script.Accept(visitor);if(visitor.Functions.Any(function=>function.FunctionName.Value.ToUpperInvariant() is "GETDATE" or "GETUTCDATE" or "SYSDATETIME" or "SYSUTCDATETIME" or "NEWID" or "RAND" or "NEWSEQUENTIALID")){throw new SqlQueryException("A nondeterministic computed column cannot be persisted.",4936);}foreach(var call in visitor.Functions.Where(static call=>call.CallTarget is MultiPartIdentifierCallTarget)){var target=(MultiPartIdentifierCallTarget)call.CallTarget;var owner=target.MultiPartIdentifier.Identifiers.Last().Value;var name=call.FunctionName.Value;var key=owner+"."+name;var routine=catalog.Schemas.FirstOrDefault(schema=>schema.Name.Equals(owner,StringComparison.OrdinalIgnoreCase))?.Routines.FirstOrDefault(routine=>routine.Name.Equals(name,StringComparison.OrdinalIgnoreCase));if(routine is not{IsSchemaBound:true,Definition:not null}){throw new SqlQueryException("A persisted computed UDF must be deterministic and schema-bound.",4936);}active??=new(StringComparer.OrdinalIgnoreCase);if(!active.Add(key)){throw new SqlQueryException("A recursive function is not accepted as a persisted computed expression.",4936);}var body=new TSql160Parser(true).Parse(new StringReader(routine.Definition),out _);var references=new References();body.Accept(references);if(references.Tables.Count>0){throw new SqlQueryException("A persisted computed UDF cannot depend on table data.",4936);}foreach(var function in references.Functions){var generator=new Sql160ScriptGenerator();generator.GenerateScript(function,out var text);ValidatePersisted(text,catalog,active);}active.Remove(key);}
    }
    private sealed class References:TSqlFragmentVisitor{
        internal List<ColumnReferenceExpression> Columns{get;}=[];internal List<FunctionCall> Functions{get;}=[];internal List<NamedTableReference> Tables{get;}=[];
        public override void ExplicitVisit(ColumnReferenceExpression node){this.Columns.Add(node);base.ExplicitVisit(node);}
        public override void ExplicitVisit(FunctionCall node){this.Functions.Add(node);base.ExplicitVisit(node);}
        public override void ExplicitVisit(NamedTableReference node){this.Tables.Add(node);base.ExplicitVisit(node);}
        public override void ExplicitVisit(ScalarSubquery node)=>throw new SqlQueryException("Subqueries are not allowed in computed column expressions.",1046);
    }
}
